const input = $input.first();
const rawJson = (input && input.json) || {};

let triggerSource = 'mattermost';
let rawBody = {};

try {
  const trigWebhook = $('Webhook Trigger (jira-push-spec)').first();
  if (trigWebhook && trigWebhook.json) {
    triggerSource = 'webhook';
    rawBody = trigWebhook.json.body || trigWebhook.json;
  }
} catch (e) {}

if (triggerSource !== 'webhook') {
  try {
    const trigExec = $('Execute Workflow Trigger').first();
    if (trigExec && trigExec.json) {
      triggerSource = 'mattermost';
      rawBody = trigExec.json.body?.params || trigExec.json.body || trigExec.json.params || trigExec.json;
    }
  } catch (e) {}
}

const payload = Object.assign({}, rawJson, rawBody);
const rawKey = payload.issueKey || '';
const rawProject = (payload.project || '').trim();
const userName = payload.userName || 'User';
const isDryRun = Boolean(payload.dryRun);

const match = String(rawKey).match(/([A-Z][A-Z0-9]*-\d+)/i);
const issueKey = match ? match[1].toUpperCase() : '';

if (!issueKey) {
  const errMsg = `🚨 **[Lỗi Cú Pháp]** Không tìm thấy mã Jira \`issueKey\` hợp lệ trong lệnh.\n> Cú pháp: \`/agent [project] push-jira [issueKey]\`\n> Ví dụ: \`/agent 3.1 push-jira G3PTP-17396\``;
  return [{
    json: {
      isError: true,
      errorType: 'INVALID_ISSUE_KEY',
      reportText: errMsg,
      _triggerSource: triggerSource,
      userName
    }
  }];
}

return [{
  json: {
    isError: false,
    issueKey: issueKey,
    project: rawProject,
    targetPath: 'spec/refined.md',
    readContent: true,
    dryRun: isDryRun,
    userName: userName,
    _triggerSource: triggerSource
  }
}];

const fs = require('fs');
const path = require('path');

const input = $input.first();
const resolveRes = (input && input.json) || {};
const prepContext = $('Prepare Resolver Input').first()?.json || {};

const triggerSource = prepContext._triggerSource || resolveRes._triggerSource || 'mattermost';
const issueKey = prepContext.issueKey || resolveRes.issueKey || '';
const userName = prepContext.userName || resolveRes.userName || 'User';
const isDryRun = Boolean(prepContext.dryRun || resolveRes.dryRun);

// 1. Kiểm tra kết quả từ Workspace Resolver
if (resolveRes.isError || !resolveRes.found) {
  return [{
    json: {
      isError: true,
      errorType: resolveRes.errorType || 'FILE_NOT_FOUND',
      reportText: resolveRes.reportText || `🚨 Không tìm thấy file spec/refined.md cho vé ${issueKey}`,
      _triggerSource: triggerSource,
      userName,
      issueKey
    }
  }];
}

const targetFilePath = resolveRes.filePath;
const markdownContent = resolveRes.fileContent || '';

if (!markdownContent.trim()) {
  return [{
    json: {
      isError: true,
      errorType: 'EMPTY_FILE',
      reportText: `🚨 **[File Spec Rỗng]** File tại \`${targetFilePath}\` không có nội dung.`,
      _triggerSource: triggerSource,
      userName,
      issueKey
    }
  }];
}

// 2. Pre-flight Quality Gate
const qualityErrors = [];
if (/\[\.\.\.\]/.test(markdownContent)) {
  qualityErrors.push("Spec còn chứa placeholder chưa điền: `[...]`");
}
const forbiddenSections = [
  /##\s*Giả định\s*(&|và)\s*Rủi ro/i,
  /##\s*Ngoài Phạm vi/i,
  /##\s*Đánh giá Độ tin cậy/i
];
for (const pattern of forbiddenSections) {
  if (pattern.test(markdownContent)) {
    qualityErrors.push(`Spec còn chứa section nội bộ bị cấm trên Jira: \`${pattern.source}\``);
  }
}
if (!markdownContent.includes('Given') || !markdownContent.includes('When') || !markdownContent.includes('Then')) {
  qualityErrors.push("Acceptance Criteria bắt buộc phải có cấu trúc Gherkin chuẩn (`Given` / `When` / `Then`).");
}

if (qualityErrors.length > 0) {
  const errMsg = `⚠️ **[Chặn Ghi Đè - Spec Chưa Đạt Chuẩn]** File \`refined.md\` của ticket **${issueKey}** chưa hoàn thiện:\n` +
                 qualityErrors.map(e => `> - ${e}`).join('\n') + '\n\n' +
                 `*Vui lòng mở file \`${targetFilePath}\` để hoàn thiện spec trước khi đẩy lên Jira.*`;
  return [{
    json: {
      isError: true,
      errorType: 'PREFLIGHT_FAILED',
      reportText: errMsg,
      _triggerSource: triggerSource,
      userName,
      issueKey,
      filePath: targetFilePath
    }
  }];
}

// 3. Chuyển đổi Markdown sang ADF
const projectRoot = ($env && $env.AGENT_WORKSPACE_DIR) || '/Users/qa-quangnt/Desktop/Project/Test/agent-skills';
let adfContent = null;
try {
  const scriptPath = path.join(projectRoot, 'plugins/ba-po/skills/ba-refine/assets/jira-push-spec.js');
  if (fs.existsSync(scriptPath)) {
    const { markdownToAdf } = require(scriptPath);
    adfContent = markdownToAdf(markdownContent);
  }
} catch (e) {}

if (!adfContent) {
  adfContent = {
    version: 1,
    type: 'doc',
    content: [
      {
        type: 'paragraph',
        content: [{ type: 'text', text: markdownContent }]
      }
    ]
  };
}

const tableCount = (adfContent.content || []).filter(n => n.type === 'table').length;
const blockCount = (adfContent.content || []).length;

return [{
  json: {
    isError: false,
    issueKey,
    project: resolveRes.project || prepContext.project,
    filePath: targetFilePath,
    dryRun: isDryRun,
    adfContent,
    tableCount,
    blockCount,
    diagramPaths: resolveRes.diagramPaths || [],
    userName,
    _triggerSource: triggerSource
  }
}];

const input = $input.first();
const json = (input && input.json) || {};

let specContext = {};
try {
  specContext = $('Pre-flight Gate & ADF Converter').first()?.json || {};
} catch (e) {}

const triggerSource = specContext._triggerSource || json._triggerSource || 'mattermost';
const issueKey = specContext.issueKey || json.issueKey || '';
const userName = specContext.userName || json.userName || 'User';
const baseUrl = ($env && $env.ATLASSIAN_BASE_URL) || 'https://entrade.atlassian.net';

// 1. Trường hợp có lỗi từ bước Resolve/Pre-flight
if (specContext.isError || json.isError) {
  return [{
    json: {
      success: false,
      isError: true,
      issueKey,
      reportText: specContext.reportText || json.reportText,
      _triggerSource: triggerSource
    }
  }];
}

// 2. Trường hợp Dry Run
if (specContext.dryRun) {
  const dryRunMsg = `🧪 **[DRY RUN - Xem Trước Spec ADF]** Cho ticket [${issueKey}](${baseUrl}/browse/${issueKey}):\n` +
                    `- **Nguồn file:** \`${specContext.filePath}\`\n` +
                    `- **Tổng số block:** ${specContext.blockCount} blocks (gồm ${specContext.tableCount} bảng)\n` +
                    `> *Lưu ý: Chế độ Dry Run không ghi đè dữ liệu lên Jira.*`;
  return [{
    json: {
      success: true,
      isDryRun: true,
      issueKey,
      reportText: dryRunMsg,
      _triggerSource: triggerSource
    }
  }];
}

// 3. Trường hợp Live Push - kiểm tra phản hồi từ Jira API
if (json.error || json.errorMessages || (json.status && json.status >= 400)) {
  const errMsg = (json.errorMessages && json.errorMessages.join(', ')) ||
                 (json.error && (json.error.message || json.error.description)) ||
                 'Lỗi không xác định từ Jira REST API';
  const failText = `🚨 **[Lỗi Ghi Đè Jira]** Không thể cập nhật Description cho ticket [${issueKey}](${baseUrl}/browse/${issueKey}):\n> ${errMsg}\n\n*Gợi ý: Kiểm tra quyền hạn của tài khoản hoặc cấu trúc ADF.*`;
  return [{
    json: {
      success: false,
      isError: true,
      issueKey,
      reportText: failText,
      _triggerSource: triggerSource
    }
  }];
}

const formattedUser = userName ? (userName.startsWith('@') ? userName : '@' + userName) : '@User';
const successMsg = `✅ **[Jira Spec Pusher]** Đã cập nhật thành công Description cho ticket **[${issueKey}](${baseUrl}/browse/${issueKey})**!\n` +
                   `- **Nguồn file:** \`${specContext.filePath}\`\n` +
                   `- **Dự án/Cluster:** \`${specContext.project || 'Tự động phát hiện'}\`\n` +
                   `- **Thống kê:** ${specContext.blockCount || 0} ADF blocks (bao gồm ${specContext.tableCount || 0} bảng nghiệp vụ & AC Gherkin)\n` +
                   `- **Người thực hiện:** ${formattedUser}\n\n` +
                   `👉 [Nhấp vào đây để xem trực tiếp trên Jira](${baseUrl}/browse/${issueKey})`;

return [{
  json: {
    success: true,
    isError: false,
    issueKey,
    jiraUrl: `${baseUrl}/browse/${issueKey}`,
    filePath: specContext.filePath,
    reportText: successMsg,
    _triggerSource: triggerSource
  }
}];
